// First-pass voice controls; profiles and immutable versions are backend-owned.
export function speakerVoiceId(s,p){return s?.voice?.adapter||s?.voice_profile?.config?.adapter||p.models.synthesis.id;}
export function clipVoiceId(l,s,p){return l?.voice?.adapter||(l?.voice_profile?l.voice_profile.config.adapter:speakerVoiceId(s,p));}
export function voiceLibraryPanel({p,profiles,state,speaker,busy,H,button,field,select,opt}){
  const binding=speaker?.voice_profile;
  return `<p class="modal-intro">Save character voices once and reuse them across projects. Assignments keep a specific version; changes in the library never silently update a project.</p><div class="models-grid"><fieldset class="model-card"${busy?' disabled':''}><strong>Save ${H(speaker?.name??'speaker')} as a library voice</strong>${field('Voice name','library.name',state.name||speaker?.name||'')}${field('Description','library.description',state.description)}<p>Uses this speaker’s current engine, settings and uploaded/original reference. Recordings are copied into the library.</p>${button('save-library-voice','Save new voice','primary')}${binding?button('revise-library-voice',`Save version ${binding.version+1}`,'secondary','Create a new version; existing projects keep their selected version'):''}</fieldset><fieldset class="model-card"${busy?' disabled':''}><strong>Design a new voice · Qwen3-TTS</strong>${field('Voice description','library.design',state.design)}${field('Audition text','library.text',state.text)}${select('Device','library.device',['cuda','cpu'].map(v=>opt(v,v.toUpperCase(),v===state.device)).join(''))}<p>Run Install-Voice-Design.cmd first. Generate an audition, listen, then save a chosen sample for consistent reference cloning.</p>${button('design-library-voice','Generate audition','secondary')}</fieldset></div>
  ${(p.voice_designs??[]).length?`<h3>Voice auditions</h3>${[...p.voice_designs].reverse().map(d=>`<div class="voice-library-row"><span><strong>${H(d.description)}</strong><small>${H(d.text)}</small></span>${button('preview-designed-voice','Listen','secondary','',false,`data-id="${d.id}"`)}${button('save-designed-voice','Save as voice','secondary','Save this audition as a reusable reference',busy,`data-id="${d.id}"`)}</div>`).join('')}`:''}
  <h3>Saved voices</h3><div class="voice-library-list">${profiles.map(v=>`<div class="voice-library-row"><span><strong>${H(v.name)}</strong><small>Version ${v.version}${v.archived?' · Archived':''}${binding?.id===v.id?` · This project uses v${binding.version}`:''}</small></span>${button('assign-library-voice',binding?.id===v.id&&binding.version<v.version?'Use latest version':'Assign to speaker','secondary','',busy,`data-id="${v.id}" data-version="${v.version}"`)}${button('archive-library-voice',v.archived?'Restore':'Archive','text-button','Archived voices remain available to existing projects',busy,`data-id="${v.id}" data-archived="${!v.archived}"`)}</div>`).join('')||'<p>No saved voices yet. Save a speaker voice or design an audition.</p>'}</div>`;
}

export function clipVoiceControls({l,s,p,profiles,models,H,button,field,select,opt,modelFields}){
  const voice=l.voice??{},id=clipVoiceId(l,s,p),adapter=models.find(m=>m.id===id),binding=l.voice_profile;
  const takes=p.takes?.[l.id]??[];
  return `<div class="inspector-section-title divider-top">CLIP VOICE OVERRIDES</div>${select('Saved voice for this clip','clip-profile',opt('','Inherit speaker voice',!binding)+profiles.filter(v=>!v.archived||v.id===binding?.id).map(v=>opt(v.id,v.name+' · latest v'+v.version,v.id===binding?.id)).join(''))}${binding?`<p class="inspector-note">Pinned to ${H(binding.name)} v${binding.version}. Choosing the voice again explicitly adopts its latest version.</p>`:''}${select('Clip engine','clip.adapter',opt('','Inherit voice engine',!voice.adapter)+models.filter(m=>m.capability==='synthesis').map(m=>opt(m.id,m.label,m.id===voice.adapter)).join(''))}<details><summary>Clip model settings</summary>${modelFields(adapter,voice.settings??{},'clip-setting')}</details>
  ${adapter?.supports_delivery?field('Delivery · this clip only','clip.delivery',voice.delivery??''):voice.delivery?`<p class="warning-box">This engine does not support delivery instructions. ${button('clear-clip-delivery','Clear instruction','text-button')}</p>`:''}
  ${adapter?.supports_seed?field('Generation seed · blank for variation','clip.seed',voice.seed??'','number','min="0" max="2147483647" step="1"'):''}
  ${select('Reference for this clip','clip.reference_mode',['inherit','source','sample','none'].map((v,i)=>opt(v,['Inherit assigned voice','Original speaker dialogue','Separate sample for this clip','No reference'][i],v===(voice.reference_mode??'inherit'))).join(''))}
  ${voice.reference_mode==='sample'?button('clip-reference','Attach clip sample','secondary full-width'):''}
  ${voice.reference?button('preview-clip-reference','Listen to clip sample','text-button'):''}
  ${field('Reference transcript · exact spoken sample','clip.reference_text',voice.reference_text??'')}
  ${button('clear-clip-voice','Reset clip overrides','text-button')}
  <div class="inspector-section-title divider-top">SAVED TAKES</div>${takes.length?select('Use a saved take','selected-take',opt('','Choose a take',!takes.some(t=>t.audio.asset===l.audio?.asset))+takes.map((t,i)=>opt(t.id,`Take ${i+1} · ${t.audio.kind} · ${t.audio.duration.toFixed(1)}s`,t.audio.asset===l.audio?.asset)).join('')):'<p class="inspector-note">Generated and imported takes appear here. Changing text or voice keeps previous takes.</p>'}`;
}
